extern "C" int strcmp(const char *, const char *);

typedef unsigned int nslSoundId;
enum nslSoundStatusEnum
{
	NSL_SOUNDSTATUS_INVALID = 0
};

extern nslSoundStatusEnum nslGetSoundStatus(nslSoundId sound);
extern void nslStopSound(nslSoundId sound);

enum
{
	LEVEL_INDOOR_1,
	LEVEL_INDOOR_2
};

struct TutorialStep
{
	char vo_name_string[100];
};

extern TutorialStep GTutorialStep[];

class game
{
	char pad[548];
	int level_id;
public:
	int get_level_id() { return level_id; }
};

extern game *g_game_ptr;

class IGOTutorialManager
{
	char pad0[40];
	int current_step;
	char pad1[16];
	nslSoundId current_VO;
public:
	nslSoundId play_sound(const char *name);
	void PlayCurrentVO(bool intro);
};

void IGOTutorialManager::PlayCurrentVO(bool intro)
{
	//  Stop the old sound.
	if (nslGetSoundStatus(current_VO) != NSL_SOUNDSTATUS_INVALID)
		nslStopSound(current_VO);

	//  Start the new sound
	if (!intro)
	{
		if (strcmp(GTutorialStep[current_step].vo_name_string, "TUTORIAL_NONE"))
			current_VO = play_sound(GTutorialStep[current_step].vo_name_string);
	}
	else
	{
		if (g_game_ptr->get_level_id() == LEVEL_INDOOR_1)
			current_VO = play_sound("TUTORIAL_OPENING_BEGINNER");
		else if (g_game_ptr->get_level_id() == LEVEL_INDOOR_2)
			current_VO = play_sound("TUTORIAL_OPENING_INTERMEDIATE");
		else
			current_VO = play_sound("TUTORIAL_OPENING_ADVANCE");
	}
}
